mesh@ops:~$ kubectl get virtualservice ratings -n shop -o yaml | sed -n '/http:/,$p'
  http:
  - route:
    - destination: {{host: ratings}}
    retries:
      attempts: {retryPolicy == "more" ? "20" : retryPolicy == "sane" ? "2" : retryPolicy == "none" ? "0" : "10"}
      perTryTimeout: {retryPolicy == "sane" ? "1s" : "30s"}
      retryOn: 5xx,connect-failure
    {retryPolicy == "sane" ? "timeout: 3s" : "# no timeout"}

mesh@ops:~$ promtool query instant http://prometheus:9090 'sum by (destination_pod, response_code) (rate(istio_requests_total{{destination_workload="ratings-v1"}}[1m]))'
ratings-v1-a 200  {retriesSane ? "41" : "118"}
ratings-v1-b 200  {retriesSane ? "40" : "121"}
ratings-v1-c 503  {outlierOk ? "0.2" : retriesSane ? "38" : "112"}

mesh@ops:~$ kubectl get destinationrule ratings -n shop -o yaml | sed -n '/trafficPolicy:/,$p'
  trafficPolicy:
    loadBalancer: {{simple: ROUND_ROBIN}}
{ejection == "off" ? "    # no outlierDetection" : ejection == "half" ? "    outlierDetection: consecutive5xxErrors 3, interval 10s, baseEjectionTime 30s, maxEjectionPercent 50" : "    outlierDetection: consecutive5xxErrors 1, interval 10s, baseEjectionTime 300s, maxEjectionPercent 100"}
